<?php
namespace App\Domain\Storage\Services;
use RuntimeException;use Symfony\Component\Process\Process;
class PdfInspector{public function inspect(string $absolutePath):array{if(!is_file($absolutePath))throw new RuntimeException('Uploaded file cannot be inspected.');$handle=fopen($absolutePath,'rb');$header=fread($handle,5);fclose($handle);if($header!=='%PDF-')throw new RuntimeException('The uploaded file does not contain a valid PDF signature.');$finfo=new \finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($absolutePath);if(!in_array($mime,['application/pdf','application/x-pdf'],true))throw new RuntimeException('The uploaded content is not recognized as a PDF.');$sha=hash_file('sha256',$absolutePath);$pages=null;$binary=(string)config('dms.pdfinfo_binary','pdfinfo');try{$process=new Process([$binary,$absolutePath]);$process->setTimeout(30);$process->run();if($process->isSuccessful()&&preg_match('/^Pages:\s+(\d+)/mi',$process->getOutput(),$m))$pages=(int)$m[1];}catch(\Throwable $e){}return ['mime_type'=>'application/pdf','sha256'=>$sha,'size_bytes'=>filesize($absolutePath),'page_count'=>$pages];}}
